                    i += 1
                    break
                if c == '\\' and i + 1 < n and line[i + 1] in ('"', '\\'):
                    cur.append(line[i + 1])
                    i += 2
                    continue
                cur.append(c)
                i += 1
        elif ch.isspace():
            if in_word:
                out.append(''.join(cur))
                cur = []
                in_word = False
            i += 1
